const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const money=n=>new Intl.NumberFormat('en-AE',{style:'currency',currency:'AED'}).format(n);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const products=[{id:'P101',name:'Precision Laptop',price:3250,category:'Computers'},{id:'P102',name:'Laptop Dock',price:420,category:'Accessories'},{id:'P103',name:'Wireless Mouse',price:125,category:'Accessories'},{id:'P104',name:'Studio Monitor',price:1450,category:'Computers'},{id:'P105',name:'Mechanical Keyboard',price:350,category:'Accessories'},{id:'P106',name:'USB-C Adapter',price:85,category:'Accessories'}];
const seed=()=>Array.from({length:16},(_,i)=>({id:'ORD-'+(1041+i),customer:['Amira Ali','Fathi Ahmed','Noah Smith','Sara Khan'][i%4],product:products[i%6].name,amount:products[i%6].price*(i%3+1),status:['Pending','Confirmed','Shipped'][i%3]}));let orders=JSON.parse(localStorage.getItem('flowlab-orders')||'null')||seed();let session=JSON.parse(localStorage.getItem('flowlab-session')||'null');let selected=null;let pendingCancel=null;let pageNo=1,sortUp=true;let routeGeneration=0;let toastTimer;
function save(){localStorage.setItem('flowlab-orders',JSON.stringify(orders))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}function heading(k,t,p){return `<div class="eyebrow">${k}</div><h1>${t}</h1><p>${p}</p>`}function refreshSession(){$('#session-label').textContent=session?'Signed in as '+session.email:'Guest session';$('#login-open').textContent=session?'Sign out':'Sign in'}
$('#login-open').onclick=()=>{if(session){session=null;localStorage.removeItem('flowlab-session');refreshSession();toast('Signed out')}else $('#login-dialog').showModal()};$('#login-close').onclick=()=>$('#login-dialog').close();$('#login-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('email')==='qa@example.com'&&f.get('password')==='FlowLab123!'){session={email:f.get('email')};localStorage.setItem('flowlab-session',JSON.stringify(session));$('#login-error').textContent='';$('#login-dialog').close();refreshSession();toast('Welcome back. Demo session started.')}else $('#login-error').textContent='Invalid email or password.'};$('#reset').onclick=()=>{if(confirm('Reset all FlowLab demo data and sign out?')){orders=seed();session=null;save();localStorage.removeItem('flowlab-session');refreshSession();render();toast('Demo data reset')}};$('#keep-order').onclick=()=>$('#confirm-dialog').close();$('#cancel-confirm').onclick=()=>{const o=orders.find(o=>o.id===pendingCancel);if(o)o.status='Cancelled';save();$('#confirm-dialog').close();drawOrders();toast('Order cancelled')};
const views={overview(){return heading('YOUR QUALITY ENGINEERING LAB','Build confidence. Break assumptions.','A complete practice environment for Page Objects, dynamic data, browser events, and repeatable end-to-end tests.')+`<div class="stats"><div class="stat"><span>DEMO ORDERS</span><strong>${orders.length}</strong><span>Searchable & paginated</span></div><div class="stat"><span>INTERACTION AREAS</span><strong>6</strong><span>One connected workspace</span></div><div class="stat"><span>FRAME DEPTH</span><strong>2</strong><span>Nested delivery preferences</span></div><div class="stat"><span>RESETTABLE DATA</span><strong>100%</strong><span>Stored in this browser</span></div></div><div class="hero"><div><div class="eyebrow">START WITH A REAL WORKFLOW</div><h2>Create an order. Capture its ID.</h2><p>Select an autocomplete result, capture the unit price, change quantity, apply a discount, validate tax, then find your generated order in the table.</p><a class="button primary" href="#orders">Explore orders →</a></div><div class="hero-mark">◈</div></div><div class="grid"><div class="card"><h3>Dynamic interactions</h3><p>Delayed controls, keyboard suggestions, sortable records, popups, drag and drop, and progress updates.</p><a href="#interactions">Open interaction lab →</a></div><div class="card"><h3>Frames & browser events</h3><p>Same-origin nested frames, address messages, new tabs, and native JavaScript dialogs.</p><a href="#frames">Explore frames →</a></div><div class="card"><h3>Files & validation</h3><p>Multiple uploads, file metadata, CSV downloads, dates, dependent dropdowns, and required fields.</p><a href="#files">Explore forms →</a></div><div class="card"><h3>Suggested test coverage</h3><p>Clear acceptance criteria and locator examples to build your own POM framework.</p><a href="#guide">View scenarios →</a></div></div>`},orders(){return heading('COMMERCE WORKFLOW','Orders & checkout','Capture values from the UI, calculate expected results, and correlate a generated order across screens.')+`<div class="grid"><section class="card"><h2>Create an order</h2><label class="autocomplete">Find a product<input id="product-search" role="combobox" aria-autocomplete="list" aria-controls="product-options" aria-expanded="false" placeholder="Try laptop, mouse or USB" data-testid="product-search" autocomplete="off"><div id="product-options" class="suggestions" role="listbox" hidden></div></label><p id="product-loading" role="status"></p><div id="chosen" class="result">Select a product from the suggestions.</div><div class="row"><label>Quantity<input id="quantity" type="number" min="1" max="20" value="1" data-testid="quantity"></label><label>Discount code<input id="coupon" placeholder="Use QA10" data-testid="coupon"></label></div><label>Customer name<input id="customer" value="Fathi Ahmed" data-testid="customer-name"></label><button id="apply-coupon">Apply discount</button><p id="coupon-status" role="status"></p><div id="summary" class="summary" data-testid="order-summary"></div><button id="place-order" class="primary" disabled data-testid="place-order">Place demo order</button><div id="order-created" role="status" data-testid="order-created"></div></section><section class="card"><h2>Validation objectives</h2><p>The lookup waits 600 ms before displaying matching products. Use the keyboard or click a suggestion.</p><ul><li>Quantity must be between 1 and 20.</li><li>QA10 discounts the subtotal by 10%.</li><li>Tax is 5% of the discounted subtotal.</li><li>Total = subtotal − discount + tax.</li><li>Every new order has a generated identifier.</li></ul><div class="result">Demo orders use browser-local storage. Reloading keeps your orders. Reset restores the seed records.</div></section></div><section class="card"><h2>Order register</h2><div class="toolbar"><label>Search orders<input id="order-filter" placeholder="Order ID or customer" data-testid="order-filter"></label><label>Status<select id="status-filter"><option>All</option><option>Pending</option><option>Confirmed</option><option>Shipped</option><option>Cancelled</option></select></label><button id="sort-amount">Sort amount ↑</button><button id="export-orders">Export CSV</button></div><div class="table-wrap"><table data-testid="orders-table"><thead><tr><th>Select</th><th>Order ID</th><th>Customer</th><th>Product</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody id="orders-body"></tbody></table></div><div class="actions"><button id="previous-page">Previous</button><span id="page-info" role="status"></span><button id="next-page">Next</button><span id="selection-count">0 selected</span></div></section>`},interactions(){return heading('ASYNC & STATE','Interaction lab','Practise waiting for state changes rather than adding fixed sleeps.')+`<div class="grid"><section class="card"><h2>Delayed & changing elements</h2><button id="load-content">Load delayed content</button><div id="delayed-result" class="result" role="status">Not loaded</div><button id="enable-start">Enable action after 2 seconds</button><button id="enabled-action" disabled>Complete action</button><div id="action-result" role="status"></div><button id="dynamic-replace">Replace element</button><span id="changing-id" data-testid="dynamic-value">RUN-1000</span></section><section class="card"><h2>Progress & visibility</h2><button id="start-progress">Start processing</button><progress id="progress" value="0" max="100" style="width:100%;margin-top:16px"></progress><span id="progress-label" role="status">0%</span><label><input id="show-field" type="checkbox"> Show optional reference</label><label id="optional-label" hidden>Optional reference<input id="optional-reference"></label><div class="tooltip-wrap"><button>Hover or focus for help</button><span class="tooltip" role="tooltip">Capture this tooltip with Playwright.</span></div></section><section class="card"><h2>Tabs & accordion</h2><div class="tabs" role="tablist"><button role="tab" aria-selected="true" data-tab="details">Details</button><button role="tab" aria-selected="false" data-tab="history">History</button></div><div class="tab-panel" role="tabpanel" id="tab-content">Product details: Precision Laptop</div><details><summary>Expand quality requirements</summary><p>Validate visibility, state, and content after interaction.</p></details><label>Priority<select multiple id="multi-select"><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select></label></section><section class="card"><h2>Drag & drop</h2><p>Move a task into Completed. A click alternative is available for accessibility.</p><div id="task" class="draggable" draggable="true" data-testid="draggable-task">Validate checkout totals</div><div id="drop-target" class="dropzone" data-testid="drop-target">Completed tasks</div><button id="move-task">Move task to Completed</button><div id="drag-result" role="status"></div></section></div>`},frames(){return heading('BROWSER BOUNDARIES','Frames & windows','Switch frame context, capture a message, and handle native dialogs or a newly opened tab.')+`<div class="card"><h2>Embedded shipping workflow</h2><iframe src="frame.html" title="Shipping address" id="shipping-frame" data-testid="shipping-frame"></iframe><div id="frame-message" class="result" role="status">Waiting for address from the embedded form.</div></div><div class="grid"><div class="card"><h2>Native dialogs</h2><div class="actions"><button id="alert-button">Show alert</button><button id="confirm-button">Show confirm</button><button id="prompt-button">Show prompt</button></div><div id="dialog-result" class="result" role="status">No dialog handled yet.</div></div><div class="card"><h2>New browser tab</h2><p>Open a receipt preview and capture the new page event.</p><a class="button primary" target="_blank" href="receipt.html" data-testid="receipt-link">Open receipt preview ↗</a></div></div>`},files(){return heading('DATA ENTRY & TRANSFER','Files & forms','Validate required fields, dependent options, uploaded metadata, and downloaded content.')+`<div class="grid"><section class="card"><h2>Request form</h2><form id="request-form"><label>Full name<input name="name" required minlength="2"></label><label>Email address<input name="email" type="email" required></label><div class="row"><label>Country<select id="country" required><option value="">Select country</option><option>United Arab Emirates</option><option>United Kingdom</option></select></label><label>City<select id="dependent-city" required disabled><option value="">Select country first</option></select></label></div><label>Requested date<input id="request-date" type="date" required></label><label>Notes<textarea name="notes" maxlength="250"></textarea></label><label><input type="radio" name="service" value="Standard" checked> Standard <input type="radio" name="service" value="Express"> Express</label><label><input type="checkbox" name="terms" required> Confirm this is demo data</label><button class="primary">Submit request</button><div id="form-result" class="result" role="status"></div></form></section><section class="card"><h2>File upload</h2><label class="dropzone">Choose one or more files<input id="upload" type="file" multiple data-testid="file-upload"></label><div id="file-results" role="status">No files selected.</div><p class="hint">Files are inspected locally. No upload to a server occurs.</p><h2 style="margin-top:30px">Download sample</h2><button id="download-sample">Download products CSV</button><h2 style="margin-top:30px">Range & colour</h2><label>Confidence threshold<input id="threshold" type="range" min="0" max="100" value="80"></label><output id="threshold-value">80%</output><label>Label colour<input id="label-color" type="color" value="#087d75"></label><div id="color-preview" class="result">Preview label</div></section></div>`},guide(){return heading('YOUR NEXT TEST SUITE','Scenario notebook','Start with one Page Object, then connect the workflows. Every control has a label, accessible name, or a stable test identifier.')+`<div class="card">${[['01','Authentication','Valid login shows the account email; invalid login displays an error; sign out clears the session.'],['02','Autocomplete','Enter laptop, wait for two options, capture their names and select Laptop Dock using click or ArrowDown + Enter.'],['03','Dynamic totals','Capture the selected price. With quantity 3 and QA10, validate subtotal, discount, 5% tax and final total.'],['04','Order correlation','Capture the generated order ID. Search the register and verify customer, product, amount and status after reload.'],['05','Table behaviour','Filter by status, compare numeric amounts after sorting, navigate pages and select rows.'],['06','Cancellation','Open the modal, keep the order once, then cancel and verify its status.'],['07','Async controls','Wait for delayed content, enabled actions, progress completion and changing dynamic values.'],['08','Nested frames','Save a shipping address in the outer frame and confirm a delivery window in the nested frame.'],['09','Files & validation','Reject missing required fields, validate dependent cities, inspect filenames and validate CSV download content.'],['10','Browser events','Handle alert, confirm and prompt dialogs. Capture the receipt tab and verify its heading.']].map(([n,t,d])=>`<div class="scenario"><span class="eyebrow">SCENARIO ${n}</span><b>${t}</b><p>${d}</p></div>`).join('')}</div><div class="card"><h2>Playwright locator examples</h2><pre>page.getByTestId('product-search')
page.getByRole('option', { name: /Laptop Dock/ })
page.getByTestId('order-total')
page.frameLocator('#shipping-frame')
  .getByLabel('City')
page.frameLocator('#shipping-frame')
  .frameLocator('#delivery-frame')
  .getByLabel('Delivery window')</pre><p>Hosted access is private. For unattended Jenkins runs, use a local copy of the source; the outer hosting sign-in is separate from FlowLab's demo login.</p></div>`}};
let couponApplied=false;function amounts(){const q=Number($('#quantity')?.value||1),sub=(selected?.price||0)*q,discount=couponApplied?sub*.1:0,tax=(sub-discount)*.05;return {q,sub,discount,tax,total:sub-discount+tax}}function totals(){const a=amounts();$('#summary').innerHTML=`<div><span>Subtotal</span><span data-testid="order-subtotal">${money(a.sub)}</span></div><div><span>Discount</span><span data-testid="order-discount">${money(a.discount)}</span></div><div><span>Tax (5%)</span><span data-testid="order-tax">${money(a.tax)}</span></div><div class="total"><span>Total</span><span data-testid="order-total">${money(a.total)}</span></div>`;$('#place-order').disabled=!selected||!Number.isInteger(a.q)||a.q<1||a.q>20||!$('#customer').value.trim()}
function drawOrders(){if(!$('#orders-body'))return;const filter=$('#order-filter').value.toLowerCase(),status=$('#status-filter').value;const list=orders.filter(o=>(o.id.toLowerCase().includes(filter)||o.customer.toLowerCase().includes(filter))&&(status==='All'||o.status===status)).sort((a,b)=>sortUp?a.amount-b.amount:b.amount-a.amount);const pages=Math.max(1,Math.ceil(list.length/5));pageNo=Math.min(pageNo,pages);$('#orders-body').innerHTML=list.slice((pageNo-1)*5,pageNo*5).map(o=>`<tr data-order-id="${esc(o.id)}"><td><input type="checkbox" aria-label="Select ${esc(o.id)}"></td><td data-testid="order-id">${esc(o.id)}</td><td>${esc(o.customer)}</td><td>${esc(o.product)}</td><td>${money(o.amount)}</td><td><span class="pill ${o.status}">${o.status}</span></td><td><button data-cancel="${esc(o.id)}" ${o.status==='Cancelled'?'disabled':''}>Cancel</button></td></tr>`).join('')||'<tr><td colspan="7">No matching orders</td></tr>';$('#page-info').textContent=`Page ${pageNo} of ${pages} · ${list.length} orders`;$('#previous-page').disabled=pageNo===1;$('#next-page').disabled=pageNo===pages;$('#selection-count').textContent='0 selected';$$('[data-cancel]').forEach(b=>b.onclick=()=>{pendingCancel=b.dataset.cancel;$('#confirm-dialog').showModal()});$$('#orders-body input').forEach(i=>i.onchange=()=>$('#selection-count').textContent=$$('#orders-body input:checked').length+' selected')}
function download(name,rows){const text=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bindOrders(gen){selected=null;couponApplied=false;pageNo=1;totals();let timer,active=-1;const input=$('#product-search'),list=$('#product-options');input.oninput=()=>{clearTimeout(timer);selected=null;totals();list.hidden=true;input.setAttribute('aria-expanded','false');active=-1;$('#product-loading').textContent='Searching…';const query=input.value.trim().toLowerCase();timer=setTimeout(()=>{if(gen!==routeGeneration)return;const matches=query?products.filter(p=>p.name.toLowerCase().includes(query)):[];list.innerHTML=matches.map(p=>`<div role="option" id="option-${p.id}" data-product="${p.id}" aria-selected="false">${esc(p.name)} · ${money(p.price)}</div>`).join('');list.hidden=!matches.length;input.setAttribute('aria-expanded',String(!!matches.length));$('#product-loading').textContent=matches.length?`${matches.length} suggestions`:query?'No matching products':'';$$('[data-product]').forEach(el=>el.onclick=()=>choose(el.dataset.product))},600)};function choose(id){selected=products.find(p=>p.id===id);input.value=selected.name;$('#chosen').innerHTML=`<b data-testid="selected-product">${selected.name}</b><br>Unit price: <span data-testid="unit-price">${money(selected.price)}</span>`;list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');$('#product-loading').textContent='Product selected';totals()}input.onkeydown=e=>{const opts=$$('[data-product]');if(!list.hidden&&opts.length){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length;opts.forEach((o,i)=>o.setAttribute('aria-selected',String(i===active)));input.setAttribute('aria-activedescendant',opts[active].id)}if(e.key==='Enter'&&active>=0){e.preventDefault();choose(opts[active].dataset.product)}}if(e.key==='Escape'){list.hidden=true;input.setAttribute('aria-expanded','false')}};$('#quantity').oninput=totals;$('#customer').oninput=totals;$('#coupon').oninput=()=>{couponApplied=false;$('#coupon-status').textContent='';totals()};$('#apply-coupon').onclick=()=>{couponApplied=$('#coupon').value.trim().toUpperCase()==='QA10';$('#coupon-status').textContent=couponApplied?'10% discount applied':'Invalid discount code';totals()};$('#place-order').onclick=()=>{const a=amounts();const id='ORD-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase();orders.unshift({id,customer:$('#customer').value.trim(),product:selected.name,amount:Number(a.total.toFixed(2)),status:'Confirmed'});save();$('#order-created').innerHTML=`<div class="result">Order created: <b data-testid="created-order-id">${id}</b></div>`;$('#order-filter').value=id;pageNo=1;drawOrders();toast('Order created successfully')};$('#order-filter').oninput=$('#status-filter').onchange=()=>{pageNo=1;drawOrders()};$('#sort-amount').onclick=()=>{sortUp=!sortUp;$('#sort-amount').textContent='Sort amount '+(sortUp?'↑':'↓');drawOrders()};$('#previous-page').onclick=()=>{pageNo--;drawOrders()};$('#next-page').onclick=()=>{pageNo++;drawOrders()};$('#export-orders').onclick=()=>download('flowlab-orders.csv',[['Order ID','Customer','Product','Amount','Status'],...orders.map(o=>[o.id,o.customer,o.product,o.amount,o.status])]);drawOrders()}
function bindInteractions(gen){$('#load-content').onclick=()=>{$('#delayed-result').textContent='Loading…';setTimeout(()=>{if(gen===routeGeneration)$('#delayed-result').textContent='Content ready: REF-'+Date.now().toString(36).toUpperCase()},1600)};$('#enable-start').onclick=()=>{$('#enabled-action').disabled=true;setTimeout(()=>{if(gen===routeGeneration)$('#enabled-action').disabled=false},2000)};$('#enabled-action').onclick=()=>$('#action-result').textContent='Action completed';$('#dynamic-replace').onclick=()=>{$('#changing-id').outerHTML=`<span id="changing-id" data-testid="dynamic-value">RUN-${Date.now()}</span>`};$('#show-field').onchange=e=>$('#optional-label').hidden=!e.target.checked;$('#start-progress').onclick=()=>{const btn=$('#start-progress');btn.disabled=true;let n=0;const timer=setInterval(()=>{if(gen!==routeGeneration){clearInterval(timer);return}n+=10;$('#progress').value=n;$('#progress-label').textContent=n===100?'Processing complete':n+'%';if(n===100){clearInterval(timer);btn.disabled=false}},180)};$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));$('#tab-content').textContent=b.dataset.tab==='details'?'Product details: Precision Laptop':'History: product added, price verified, checkout ready'});$('#task').ondragstart=e=>e.dataTransfer.setData('text/plain','flowlab-task');$('#drop-target').ondragover=e=>e.preventDefault();function move(){$('#drop-target').append($('#task'));$('#drag-result').textContent='Task completed'}$('#drop-target').ondrop=e=>{e.preventDefault();if(e.dataTransfer.getData('text/plain')==='flowlab-task')move()};$('#move-task').onclick=move}
function bindFrames(){$('#alert-button').onclick=()=>{alert('FlowLab alert: validation ready');$('#dialog-result').textContent='Alert dismissed'};$('#confirm-button').onclick=()=>$('#dialog-result').textContent=confirm('Approve the demo request?')?'Request approved':'Request rejected';$('#prompt-button').onclick=()=>{const v=prompt('Enter an agent reference');$('#dialog-result').textContent=v===null?'Prompt cancelled':'Reference: '+v}}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('#shipping-frame')?.contentWindow&&e.data?.type==='flowlab-address')$('#frame-message').textContent='Address received from frame: '+e.data.city});
function bindFiles(){$('#country').onchange=e=>{const cities={'United Arab Emirates':['Abu Dhabi','Dubai','Sharjah'],'United Kingdom':['London','Manchester']};const choices=cities[e.target.value]||[];$('#dependent-city').disabled=!choices.length;$('#dependent-city').innerHTML='<option value="">Select city</option>'+choices.map(c=>`<option>${c}</option>`).join('')};$('#request-form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name');$('#form-result').textContent=`Request REQ-${Date.now()} created for ${name} in ${$('#dependent-city').value}`};$('#upload').onchange=e=>$('#file-results').innerHTML=[...e.target.files].map(f=>`<div class="result">${esc(f.name)} · ${f.size} bytes · ${esc(f.type||'Unknown type')}</div>`).join('')||'No files selected.';$('#download-sample').onclick=()=>download('flowlab-products.csv',[['ID','Name','Price','Category'],...products.map(p=>[p.id,p.name,p.price,p.category])]);$('#threshold').oninput=e=>$('#threshold-value').textContent=e.target.value+'%';$('#label-color').oninput=e=>$('#color-preview').style.color=e.target.value}
function render(){routeGeneration++;const key=location.hash.slice(1)||'overview',route=views[key]?key:'overview';$('#content').innerHTML=views[route]();$('#section-name').textContent={overview:'Overview',orders:'Orders & checkout',interactions:'Interaction lab',frames:'Frames & windows',files:'Files & forms',guide:'Test scenarios'}[route];$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));if(route==='orders')bindOrders(routeGeneration);if(route==='interactions')bindInteractions(routeGeneration);if(route==='frames')bindFrames();if(route==='files')bindFiles();window.scrollTo(0,0)}window.onhashchange=render;refreshSession();render();
